const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Brooklyn, New York geometry
  const brooklyn = ee.Geometry.Rectangle([-74.04, 40.65, -73.88, 40.72]);

  // Function to get mean NO2 for a date range and year
  async function getMeanNO2(year, startDay, endDay) {
    const startDate = ee.Date.fromYMD(year, 10, startDay);
    const endDate = ee.Date.fromYMD(year, 10, endDay);

    const collection = ee.ImageCollection('COPERNICUS/S5P/NRTI_L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(brooklyn)
      .filter(ee.Filter.gte('qa_value', 0.75));

    const size = collection.size().getInfo();

    if (size === 0) {
      console.log(`${year}: No images found (size: 0)`);
      return { mean: null, count: 0, size: size };
    }

    const meanImage = collection.mean();
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: brooklyn,
      scale: 5000,
      maxPixels: 1e9
    });

    const meanValue = stats.get('NO2_column_number_density').getInfo();

    const countStats = collection.first().reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: brooklyn,
      scale: 5000,
      maxPixels: 1e9
    });

    const pixelCount = countStats.get('NO2_column_number_density').getInfo();

    return { mean: meanValue, count: pixelCount, size: size };
  }

  // Get data for each year
  const result2021 = await getMeanNO2(2021, 1, 23);
  const result2019 = await getMeanNO2(2019, 1, 23);
  const result2018 = await getMeanNO2(2018, 1, 23);

  console.log(`2021 Oct 1-23: ${result2021.size} images, Mean NO2: ${result2021.mean}, Pixels: ${result2021.count}`);
  console.log(`2019 Oct 1-23: ${result2019.size} images, Mean NO2: ${result2019.mean}, Pixels: ${result2019.count}`);
  console.log(`2018 Oct 1-23: ${result2018.size} images, Mean NO2: ${result2018.mean}, Pixels: ${result2018.count}`);

  // Check for empty collections
  if (result2021.size === 0 || result2019.size === 0 || result2018.size === 0) {
    console.log('C1');
    return;
  }

  // Check for no valid pixels
  if (result2021.count === 0 || result2019.count === 0 || result2018.count === 0) {
    console.log('C2');
    return;
  }

  // Check for invalid/null values
  if (result2021.mean === null || result2019.mean === null || result2018.mean === null ||
      isNaN(result2021.mean) || isNaN(result2019.mean) || isNaN(result2018.mean) ||
      result2021.mean < 0 || result2019.mean < 0 || result2018.mean < 0) {
    console.log('C3');
    return;
  }

  // Compare: Is 2021 lower than both 2019 and 2018?
  const lower2019 = result2021.mean < result2019.mean;
  const lower2018 = result2021.mean < result2018.mean;

  console.log(`2021 lower than 2019: ${lower2019}`);
  console.log(`2021 lower than 2018: ${lower2018}`);

  if (lower2019 && lower2018) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
